SELECT p.*
FROM payment p
JOIN orders o ON o.id = p.order_id
WHERE p.pay_no = #{payNo}
  AND p.order_type = 0
  AND o.user_id = #{userId}

SELECT * FROM payment
WHERE order_id = #{orderId} AND order_type = #{orderType}
ORDER BY create_time DESC, id DESC LIMIT 1

mapper.update:
UPDATE payment
SET status = 2, trade_no = #{tradeNo}, pay_time = #{payTime}
WHERE id = #{id} AND status IN (0, 1)
